// Aggregate all translations and generate HTML files
const items = $input.all();
const fs = require('fs');

// Load template and locales
const template = `<!DOCTYPE html>
<html lang="{{LANG}}" dir="{{DIR}}">
<!-- Template content loaded from file -->
</html>`;

const locales = {
  en: { dir: 'ltr', lang_path: '' },
  de: { dir: 'ltr', lang_path: 'de/' },
  fr: { dir: 'ltr', lang_path: 'fr/' },
  it: { dir: 'ltr', lang_path: 'it/' },
  es: { dir: 'ltr', lang_path: 'es/' },
  pt: { dir: 'ltr', lang_path: 'pt/' },
  nl: { dir: 'ltr', lang_path: 'nl/' },
  ar: { dir: 'rtl', lang_path: 'ar/' },
  ja: { dir: 'ltr', lang_path: 'ja/' },
  zh: { dir: 'ltr', lang_path: 'zh/' },
  ko: { dir: 'ltr', lang_path: 'ko/' }
};

const files = [];

// Process each translation
for (const item of items) {
  const lang = item.json.target_lang;
  const translation = JSON.parse(item.json.content[0].text);
  const original = item.json.original;

  files.push({
    lang: lang,
    path: locales[lang].lang_path + original.slug + '/index.html',
    title: translation.title,
    content: translation.content,
    description: translation.description,
    slug: original.slug,
    category: original.category,
    reading_time: original.reading_time
  });
}

// Add English version
const englishOriginal = items[0].json.original;
files.unshift({
  lang: 'en',
  path: englishOriginal.slug + '/index.html',
  title: englishOriginal.title,
  content: englishOriginal.content,
  description: englishOriginal.meta_description,
  slug: englishOriginal.slug,
  category: englishOriginal.category,
  reading_time: englishOriginal.reading_time
});

return files.map(f => ({ json: f }));
